parameters.jsCode:
for (let item of $input.all()) {
  const deepCourseUnderstanding = $('Generate Deep Course Understanding').item.json.candidates?.[0]?.content?.parts?.[0]?.text || "No course summary generated";
  const studentIntel = item.json.candidates?.[0]?.content?.parts?.[0]?.text || "No student intelligence generated";
  const rawTranscript = $('Transcribe via Groq').item.json.text || "";
  const courseName = $('Webhook').item.json.body.meeting_name || "L3 Automatique";

  const fullReport = '# 📚 Academic Course Understanding & Intelligence Report

## 🧠 Course Mastery Overview
' + deepCourseUnderstanding + '

---

## 🎯 Student Intel, Homework, & Alerts
' + studentIntel + '
';

  const autoMasterPrompt = '# MASTER STUDY & TUTORING PROMPT: ' + courseName + ' (L3 AUTOMATIQUE)

## 1. Persona & Mission
You are an elite, world-class university professor in L3 Automatique & Electrical/Control Engineering. Your mission is to tutor the student through the concepts covered in this specific lecture.

## 2. Ingested Lecture Knowledge & Formulations
' + deepCourseUnderstanding + '

## 3. Professor's Explicit Warnings, Traps & Student Alerts
' + studentIntel + '

## 4. Full Transcribed Lecture Reference
' + rawTranscript + '

## 5. Tutoring Protocol
Act as a personal 1-on-1 Socratic tutor. Test the student with step-by-step questions, verify their analytical calculations, and guide them through core engineering principles.
';

  item.json = { 
    report_markdown: fullReport,
    course_understanding: deepCourseUnderstanding,
    student_intel: studentIntel,
    transcript_text: rawTranscript,
    master_prompt: autoMasterPrompt
  };
}
return $input.all();

parameters.jsonBody:
={{ {
  contents: [
    {
      parts: [
        {
          text: "You are an intelligent university class schedule tracker. Students in Algeria are posting announcements and chatting in French, Algerian Darija, and Arabic about their university courses (L3 Automatique).

Known Modules:
- Embedded Computer 1 (Calculateur Embarqué 1)
